using FusionKingdoms.Sim;
using Godot;

namespace FusionKingdoms;

// Loads the hand-drawn sprites (generated by tools/art) and assembles per-mind character sheets.
public static class ArtLibrary
{
    public const int Frame = 16;
    static readonly Dictionary<string, Texture2D> Textures = new();
    static readonly Dictionary<string, Image> Images = new();
    static readonly Dictionary<string, Texture2D> Characters = new();

    public static readonly string[] Roles = ["Farmer", "Builder", "Guard", "Scout", "Thief", "Hunter", "Healer", "Hoarder"];

    public static Texture2D Tex(string path)
    {
        if (Textures.TryGetValue(path, out var t)) return t;
        t = GD.Load<Texture2D>($"res://assets/{path}.png");
        Textures[path] = t;
        return t;
    }

    public static Image Img(string path)
    {
        if (Images.TryGetValue(path, out var i)) return i;
        i = Tex(path).GetImage();
        if (i.IsCompressed()) i.Decompress();
        i.Convert(Image.Format.Rgba8);
        Images[path] = i;
        return i;
    }

    public static string TeamName(int team) => team switch { 0 => "blue", 1 => "red", _ => "wild" };

    // The job a mind is best at decides its hat; the next best decides what it carries.
    public static (string hat, string tool) Look(Mind? m)
    {
        if (m == null) return ("Farmer", "Farmer");
        if (m.Skill.Length != Roles.Length)
        {
            var root = m;
            while (root.Parents.Length > 0) root = root.Parents[0];
            string r = Roles.Contains(root.Name) ? root.Name : "Farmer";
            if (m.Parents.Length == 2)
            {
                var other = m.Parents[1];
                while (other.Parents.Length > 0) other = other.Parents[0];
                return (r, Roles.Contains(other.Name) ? other.Name : r);
            }
            return (r, r);
        }
        // The look follows the class: main role's hat, second role's tool.
        var c = Classes.Of(m);
        return (Roles[c.A], Roles[c.B]);
    }

    // A creature sheet for wild species, or a composited human for everyone else.
    public static Texture2D SheetFor(Unit u)
    {
        string? creature = u.Species switch
        {
            Species.Sprite => "Sprite",
            Species.FoxKin => "Fox",
            Species.MothKin => "Moth",
            Species.Sage => "Sage",
            Species.Troll => u.Mind?.Name.StartsWith("Aberration") == true ? "Aberration" : u.Mind?.Name.Contains("Sealed") == true ? "Sealed" : "Troll",
            _ => null,
        };
        if (creature != null) return Tex($"characters/creature_{creature}");
        var (hat, tool) = u.IsRuler ? ("Crown", "") : Look(u.Mind);
        string hair = ((u.Mind?.Id ?? u.Id) % 3 == 0) ? "blond" : "hair";
        string key = $"{TeamName(u.Team)}|{hair}|{hat}|{tool}|{u.IsRuler}";
        if (Characters.TryGetValue(key, out var tex)) return tex;
        var team = u.Team == 1 ? "red" : u.Team == 0 ? "blue" : "wild";
        var img = Img($"characters/body_{team}_{hair}").Duplicate() as Image ?? throw new InvalidOperationException();
        if (u.IsRuler) Over(img, Img("characters/cape"));
        Over(img, Img($"characters/hat_{hat}"));
        if (tool.Length > 0) Over(img, Img($"characters/tool_{tool}_{(team == "red" ? "red" : "blue")}"));
        Outline(img);
        tex = ImageTexture.CreateFromImage(img);
        Characters[key] = tex;
        return tex;
    }

    public static int FrameSize(Unit u) => u.Species == Species.Troll ? 24 : 16;

    static void Over(Image dst, Image src)
    {
        int w = dst.GetWidth(), h = dst.GetHeight();
        for (int y = 0; y < h; y++)
        for (int x = 0; x < w; x++)
        {
            var c = src.GetPixel(x, y);
            if (c.A > 0.5f) dst.SetPixel(x, y, c);
        }
    }

    static readonly Color Ink = new("1d1626");

    // Outline each 16x16 frame separately so neighbours in the sheet don't touch.
    static void Outline(Image img)
    {
        int w = img.GetWidth(), h = img.GetHeight();
        var solid = new bool[w * h];
        for (int y = 0; y < h; y++)
        for (int x = 0; x < w; x++)
            solid[y * w + x] = img.GetPixel(x, y).A > 0.6f;
        for (int y = 0; y < h; y++)
        for (int x = 0; x < w; x++)
        {
            if (solid[y * w + x]) continue;
            bool edge = false;
            foreach (var (dx, dy) in new[] { (1, 0), (-1, 0), (0, 1), (0, -1) })
            {
                int nx = x + dx, ny = y + dy;
                if (nx < 0 || ny < 0 || nx >= w || ny >= h) continue;
                if (nx / Frame != x / Frame || ny / Frame != y / Frame) continue;
                if (solid[ny * w + nx]) { edge = true; break; }
            }
            if (edge) img.SetPixel(x, y, Ink);
        }
    }
}
